// === Tab: mySketch ===
const sketch = (p) => {
    let H = 2048;
    let W = 2048;

    let min_width;
    let max_width;

    let G;

    let SEED;

    let flocks = [];
    let base_color;

    let ID, ID2;
    let PRE_COL;

    let POSX = [];
    let POSY = [];
    let C1 = 7;
    let C4 = 100;
    let C02;
    let C2 = 4;
    let C3 = 3;

    let FRAME1 = 360;//360;
    let FRAME2 = 180;
    let FRAME3 = 180;
    let FRAME4 = 90;

    let BACK_COL;


    let T_TYPE = [];
    let T_SPEED = [];
    let T_RAD = [];
    let T_MCOH = [];
    let T_ICOH = [];

    let T_RED = [];
    let T_GREEN = [];
    let T_BLUE = [];

    let OS_X = [];
    let OS_Y = [];

    p.setup = () => {
        p.createCanvas(p.windowWidth, p.windowHeight);
        G = p.createGraphics(W, H);

        min_width = p.min(p.width, p.height);
        max_width = p.max(p.width, p.height);

        //SEED = fxrand()*998244353;
        SEED = p.random()*998244353;

        p.randomSeed(SEED);
        p.noiseSeed(SEED);

        base_color = p.random(256);

        G.rectMode(p.CENTER);
        G.noStroke();

        let bsel = p.int(p.random(2));
        let bcol = [60, 200];
        BACK_COL = bcol[bsel];

        POSX.length = 50;
        POSY.length = 50;


        ID = [0,1,2];
        ID2 = [0,1,2];
        p.shuffle(ID, true);
        p.shuffle(ID2, true);

        PRE_COL = [
            p.random(75) + 70,
            p.random(75) + 35,
            p.random(35),
        ];

        for(let i=0;i<C1;++i){
            POSX[i] = p.random(-W/3,W/3)+W/2;
            POSY[i] = p.random(-H/4,H/2)+H/2;
        }
        let cycle1 = [120, 180, 360];
        let csel = p.int(p.random(3));
        let mx_coh = 1.0;//p.random(1.3, 1.5);
        flocks.push(new Flock());
        for(let i = 0; i < 500; ++i) {
            flocks[0].add(new Particle(0, 0, 7.5, 150, FRAME1, cycle1[csel], 0.0, mx_coh, 10, p.int(p.random(C1))));
        }

        T_RED = [];
        T_GREEN = [];
        T_BLUE = [];
        for(let i=0;i<C4;++i){
            POSX[i] = p.random(-W/2,W/2)+W/2;
            POSY[i] = p.random(-H/2,H/2)+H/2;
            T_RED.push(p.random(30, 220));
            T_GREEN.push(p.random(30, 220));
            T_BLUE.push(p.random(30, 220));
        }

        let cycle4 = [45, 90];
        mx_coh = .6;
        flocks.push(new Flock());
        for(let i = 0; i < 500; ++i) {
            let csel4 = p.int(p.random(2));
            flocks[1].add(new Particle(2, 1, 1.5, 20, FRAME4, cycle4[csel4], 0.0, mx_coh, 10, p.int(p.random(C4))));
        }

        let mode = 1;
        if (mode == 1) {

            for (let ii=0;ii<2;++ii){
                let X2 = [];
                let n_tree = p.int(p.random(6, 10));
                let fdiv = 2;
                if (ii == 1){
                    n_tree = p.int(n_tree / 3 * 2);
                    fdiv = 2.5;
                }
                for(let i=0;i<n_tree;++i){
                    X2.push(p.random(-W/fdiv,W/fdiv));
                }
                C02 = n_tree;
                for(let i=0;i<C02;++i){
                    POSX[i] = X2[i] + W/2 + p.random(-15, 15);
                    POSY[i] = p.random(-H/2,-H/3) + H/3 + H/6*ii;//top
                }

                T_TYPE = [];
                T_SPEED = [];
                T_RAD = [];
                T_MCOH = [];
                T_ICOH = [];

                T_RED = [];
                T_GREEN = [];
                T_BLUE = [];

                OS_X = [];
                OS_Y = [];

                for (let i=0;i<C02;++i){
                    T_TYPE.push(0);//p.int(p.random(2)));
                    T_RED.push(p.random(50, 200));
                    T_GREEN.push(p.random(50, 200));
                    T_BLUE.push(p.random(50, 200));

                    OS_X.push(p.random(-100,100));
                    OS_Y.push(p.random(H/3));
                }

                FRAME2 = 180;
                var cycle1 = [180];
                let csel1 = p.int(p.random(1));
                mx_coh = 3.;
                flocks.push(new Flock());
                for(let i = 0; i < 300; ++i) {
                    let speed = p.random(6,12);
                    flocks[ii*2+2].add(new Particle(1, 1, speed, 20, FRAME2, cycle1[csel1],  
                                                .5, mx_coh, ii*10+15, p.int(p.random(C02))));
                }


                T_SPEED = [2.5, 2];
                T_MCOH = [0.3, 1.0];
                T_ICOH = [0.0, 0.0];
                T_RAD = [20, 20];

                FRAME3 = 180;
                let cycle2 = [90, 180];

                flocks.push(new Flock());
                for(let i = 0; i < 500; ++i) {
                    let csel2 = p.int(p.random(2));
                    let tp_sel = p.int(p.random(C02));
                    let tp = T_TYPE[tp_sel];
                    flocks[ii*2+3].add(new Particle(1, 2, T_SPEED[tp], T_RAD[tp], FRAME3, cycle2[csel2],  
                                                T_ICOH[tp], T_MCOH[tp], ii*10+5, tp_sel));
                }

            }

        }

        //let X2 = p.random(-W/2, W/2) + W/2;
        let Y2 = p.random(-H/4, H/2) + H/2;
        for(let i=0;i<C2;++i){
            POSX[i] = p.random(-W/2,W/2)+W/2;
            POSY[i] = p.random(-H/4,H/4)+Y2;
        }


    };

    p.windowResized = () => {
        p.resizeCanvas(p.windowWidth, p.windowHeight);
        min_width = p.min(p.width, p.height);
        max_width = p.max(p.width, p.height);
        p.loop();
    }

    p.draw = () => {
        p.blendMode(p.BLEND);
        p.background(BACK_COL);

        if(p.frameCount < FRAME1) {
            flocks[0].run();
        }
        else if(p.frameCount < FRAME1 + FRAME4) {
            flocks[1].run();
        }
        else if(p.frameCount < FRAME1 + FRAME4 + FRAME2) {
            flocks[2].run();
        }
        else if(p.frameCount < FRAME1 + FRAME4 + FRAME2 + FRAME3) {
            flocks[3].run();
        }
        else if(p.frameCount < FRAME1 + FRAME4 + FRAME2*2 + FRAME3) {
            flocks[4].run();
        }
        else if(p.frameCount < FRAME1 + FRAME4 + FRAME2*2 + FRAME3*2) {
            flocks[5].run();
        }

        p.image(G, (p.width-min_width)/2, (p.height-min_width)/2, min_width, min_width, 0, 0, W, H);
    };

    class Flock {
        particles;

        constructor() {
            this.particles = [];
        }

        add(particle) {
            this.particles.push(particle);
        }

        run() {
            this.update();
            this.display();
        }

        update() {
            for (let i = 0; i < this.particles.length; ++i) {
                this.particles[i].update(this.particles);
            }
        }

        display() {
            for (let i = 0; i < this.particles.length; ++i) {
                this.particles[i].display();
            }
        }
    }

    class Particle {
        acceleration;
        velocity;
        position;
        radius;
        max_r;
        color;
        col_sep;
        maxforce = 1.0;
        maxspeed = 2.5;
        minspeed = 0.001;
        mode;
        base;
        ali_f = 0.0;
        coh_f = 0.0;
        max_coh;
        alpha;
        fcnt;
        cycle;
        lcnt;
        fin;

        constructor(mode, base, speed, max_r, lcnt, cycle, coh, mxcoh, alpha, sel) {
            this.acceleration = p.createVector(0, 0);

            this.mode = mode;
            this.base = base;
            let offset_x;
            let offset_y;

            this.radius = 1;
            this.alpha = alpha;

            //let sel;
            if(this.base == 0){
                this.maxspeed = speed;
                this.col_sep = 0.5;
                this.position = p.createVector(POSX[sel], POSY[sel]);
                this.max_r = max_r;
                this.velocity = p.createVector(p.random(-1, 1), p.random(-1, 1));
            }
            if (this.mode == 1) {
                if(this.base == 1) {
                    offset_y = H/2;
                    this.maxspeed = speed;
                    this.col_sep = 0.5;
                    this.position = p.createVector(POSX[sel] + p.random(-5,5), POSY[sel] + offset_y);
                    this.max_r = max_r;
                    this.velocity = p.createVector(p.random(-1, 1), p.random(0.5, 1));//;p.createVector(p.random(-1, 1), p.random(-1, 1));
                }
                else if(this.base == 2){
                    if(T_TYPE[sel] == 0){
                        offset_y = p.random(H/2);
                        this.maxspeed = speed * (offset_y / H) * (offset_y / H) * 5;
                        this.col_sep = 0.5;
                        this.position = p.createVector(POSX[sel], p.max(5, POSY[sel] + offset_y));
                        this.max_r = max_r + offset_y / H * 50;
                        this.velocity = p.createVector(p.random(-1, 1), p.random(0.1, 1));
                    }
                    else {
                        offset_x = OS_X[sel];
                        offset_y = OS_Y[sel];
                        this.maxspeed = speed;
                        this.col_sep = 0.5;
                        this.position = p.createVector(POSX[sel] + offset_x, POSY[sel] + offset_y);
                        this.max_r = max_r;
                        this.velocity = p.createVector(p.random(-1, 1), p.random(-1, 1));
                    }
                }

            }
            else if (this.mode == 2){
                let ratio = POSY[sel] / H + 0.2;
                this.maxspeed = speed * 1.2 * ratio;
                this.radius = this.radius * 1.2 * ratio;
                this.alpha = this.alpha * 1.2 * ratio;
                if(this.base == 1){
                    this.col_sep = 0.5;
                    this.position = p.createVector(POSX[sel], POSY[sel]);
                    this.max_r = max_r;
                    this.velocity = p.createVector(p.random(-1, 1), p.random(-1, 1));
                }
                // else if(this.base == 2){
                //     this.col_sep = 0.5;
                //     this.position = p.createVector(POSX[sel], POSY[sel]);
                //     this.max_r = max_r;
                //     this.velocity = p.createVector(p.random(-1, 1), p.random(-1, 1));
                // }
            }




            //color
            if(this.base == 0){
                this.color = p.createVector(
                    p.max(0, PRE_COL[ID[0]] + p.random(-50,30)),
                    p.max(0, PRE_COL[ID[1]] + p.random(-50,30)),
                    p.max(0, PRE_COL[ID[2]] + p.random(-50,30)),
                );
            }
            if (this.mode == 1){
                if(this.base == 1){
                    this.color = p.createVector(
                        p.min(255, p.max(0, 200 - PRE_COL[ID[0]] + T_RED[sel] / 6 + p.random(-100,0))),
                        p.min(255, p.max(0, 200 - PRE_COL[ID[1]] + T_GREEN[sel] / 6 + p.random(-100,0))),
                        p.min(255, p.max(0, 200 - PRE_COL[ID[2]] + T_BLUE[sel] / 6 + p.random(-100,0))),
                    );
                }
                else if(this.base == 2){
                    this.color = p.createVector(
                        p.min(255, p.max(0, T_RED[sel] + p.random(-50,50))),
                        p.min(255, p.max(0, T_GREEN[sel] + p.random(-50,50))),
                        p.min(255, p.max(0, T_BLUE[sel] + p.random(-50,50))),
                    );
                }
            }
            else if (this.mode == 2){
                if(this.base == 1){
                    this.color = p.createVector(
                        p.min(255, p.max(0, T_RED[sel] + p.random(-30,30))),
                        p.min(255, p.max(0, T_GREEN[sel] + p.random(-30,30))),
                        p.min(255, p.max(0, T_BLUE[sel] + p.random(-30,30))),
                    );
                }
                else if(this.base == 2){
                    this.color = p.createVector(
                        p.max(100, p.min(255, PRE_COL[ID[0]] + p.random(0,100))),
                        p.max(100, p.min(255, PRE_COL[ID[1]] + p.random(0,100))),
                        p.max(100, p.min(255, PRE_COL[ID[2]] + p.random(0,100))),
                    );
                }
            }

            this.ali_f = coh;
            this.coh_f = coh;
            this.max_coh = mxcoh;

            this.fcnt = 0;
            this.cycle = cycle;
            this.fin = false
            this.lcnt = lcnt;
        }

        applyForce(force) {
            this.acceleration.add(force);
        }

        inner_update(particles) {
            let sep = this.separate(particles);
            let ali = this.align(particles);
            let coh = this.cohesion(particles);

            sep.mult(1.5);
            ali.mult(this.ali_f);
            coh.mult(this.coh_f);

            this.applyForce(sep);
            this.applyForce(ali);
            this.applyForce(coh);
        }

        update(particles) {
            if(this.fcnt >= this.lcnt) {this.fin = true;}
            if(this.fin){
                return;
            }
            this.inner_update(particles);

            this.velocity.add(this.acceleration);
            if (this.base == 0) {
                if(this.fcnt < this.lcnt / 2) {
                    this.velocity.add(p.createVector(
                        0, -0.1
                    ));
                }
            }
            else if (this.mode == 1 && this.base == 1) {
                this.velocity.add(p.createVector(
                    0.0, 0.2
                ));
            }
            else {
                if(this.fcnt < this.lcnt / 2) {
                    this.velocity.add(p.createVector(
                        -0.0, 0
                    ));
                }
            }

            this.velocity.limit(this.maxspeed);
            this.position.add(this.velocity);
            this.border();
            this.acceleration.mult(0);

            this.radius = p.abs(p.sin(this.fcnt/this.cycle*p.PI)) * this.max_r + 1;

            if(this.base == 0){
                this.ali_f = p.min(1.0, this.ali_f+0.05);
                this.coh_f = p.min(this.max_coh, this.coh_f+0.05);
            }
            else if (this.mode == 1 && this.base == 1) {
                this.ali_f = p.min(1.5, this.ali_f+0.03);
                this.coh_f = p.min(this.max_coh, this.coh_f+0.05);
            }
            else{
                this.ali_f = p.min(.7, this.ali_f+0.1);
                this.coh_f = p.min(this.max_coh, this.coh_f+0.05);
            }

            if(this.fcnt < this.lcnt){
                this.fcnt += 1;
            }

        }

        border() {
            //if(this.base != 1 || this.mode != 1){
                if(this.position.x > W) {this.position.x -= W;}
                else if(this.position.x < 0) {this.position.x += W;}
            if((this.base != 1 || this.mode != 1) && this.mode != 2){
                if(this.position.y > H) {this.position.y -= H;}
                else if(this.position.y < 0) {this.position.y += H;}
            }
        }

        seek(target){
            let v = p5.Vector.sub(target, this.position);
            v.normalize();
            v.mult(this.maxspeed);
            v.sub(this.velocity);
            v.limit(this.maxforce);
            return v;
        }

        separate(particles) {
            let inter_range = 128.0;
            var v = p.createVector(0, 0, 0);
            for (let i = 0; i < particles.length; i++) {
                let d = p5.Vector.dist(this.position, particles[i].position);
                if (d <= 0) continue;

                let col_diff = p5.Vector.sub(this.color, particles[i].color).mag() - 110;
                if (d < inter_range + col_diff * this.col_sep) {
                    let diff = p5.Vector.sub(this.position, particles[i].position);
                    diff.normalize();
                    diff.div(d);
                    v.add(diff);
                }
            }

            if (v.mag() > 0) {
                v.normalize();
                v.mult(this.maxspeed);
                v.sub(this.velocity);
                v.limit(this.maxforce);
            }

            return v;
        }

        align(particles) {
            var inter_range = 128.0;
            var v = p.createVector(0, 0, 0);
            let count = 0;
            for (let i = 0; i < particles.length; i++) {
                var d = p5.Vector.dist(this.position, particles[i].position);
                //let col_diff = p.abs(this.color - particles[i].color) - 128;
                var col_diff = p5.Vector.sub(this.color, particles[i].color).mag() - 110;
                if ((d > 0) && (d < inter_range - col_diff * this.col_sep)) {
                    v.add(particles[i].velocity);
                    count++;
                }
            }
            if (count > 0) {
                v.div(count);
                v.normalize();
                v.mult(this.maxspeed);
                v.sub(this.velocity);
                v.limit(this.maxforce);
                return v;
            } else {
                return p.createVector(0, 0, 0);
            }
        }

        cohesion(particles) {
            let neighbor_range = 128.0;
            var v = p.createVector(0, 0, 0);
            var count = 0;
            for (let i = 0; i < particles.length; i++) {
                var d = p5.Vector.dist(this.position, particles[i].position);

                var col_diff = p5.Vector.sub(this.color, particles[i].color).mag() - 110;
                if ((d > 0) && (d < neighbor_range - col_diff * this.col_sep)) {                   
                    v.add(particles[i].position);

                    count++;
                }
            }
            if (count > 0) {
                v.div(count);
                return this.seek(v);
            }
            else {
                return p.createVector(0, 0, 0);
            }
        }

        display(){
            if(this.fin){return;}
            var ratio = 1.0;
            //if (this.base == 0){ 
                //ratio = (H - this.position.y) / H * 1. + p.random(1.0);
                ratio = .8 + p.random(.5);
            //}
            if(this.base == 0){
                ratio = ratio * (3.0 - 3 * p.sqrt(this.position.y / H) * p.random(0.8, 1.2));
            }
            if(this.mode == 1 && this.base == 2) {
                ratio = ratio + p.random(-.2, 1.);
            }
            G.strokeWeight(this.radius);
            G.stroke(this.color.x * ratio, this.color.y * ratio, this.color.z * ratio, this.alpha);
            G.point(
                this.position.x,
                this.position.y
            )

        }
    }


    p.keyPressed = () => {
        if(p.key == 's') {
            p.save("Flocked.png");
        }
        if(p.key == 'g') {
            G.save("Flocked2048.png");
        }
    }


};

new p5(sketch);

